const art=document.querySelector('#society-art'),ctx=art.getContext('2d'),pause=document.querySelector('#art-pause');let w=600,h=300,t=0,run=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=0;const nodes=Array.from({length:75},(_,i)=>({phase:i*2.399963,ring:Math.sqrt((i+.5)/75),speed:.4+(i%7)*.07}));
function draw(){ctx.clearRect(0,0,w,h);const points=nodes.map((n,i)=>{const angle=n.phase+t*n.speed*.12;return{x:w*.5+Math.cos(angle)*n.ring*w*.42+Math.sin(t*.3+n.phase)*18,y:h*.5+Math.sin(angle)*n.ring*h*.38+Math.cos(t*.2+n.phase)*12}});for(let i=0;i<points.length;i++){const a=points[i];for(let j=i+1;j<points.length;j++){const b=points[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<68){ctx.strokeStyle='rgba(220,98,73,'+((1-d/68)*.28)+')';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}ctx.fillStyle=i%5===0?'#e85242':'rgba(205,184,169,'+(.4+nodes[i].ring*.5)+')';ctx.beginPath();ctx.arc(a.x,a.y,i%5===0?3.1:1.7,0,Math.PI*2);ctx.fill()}}
new ResizeObserver(()=>{const r=art.getBoundingClientRect();w=r.width;h=r.height;art.width=w*devicePixelRatio;art.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}).observe(art);function sync(){pause.textContent=run?'Pause Ⅱ':'Play ▷';pause.setAttribute('aria-label',run?'Pause artwork':'Play artwork')}pause.addEventListener('click',()=>{run=!run;sync()});function frame(ts){if(run&&!document.hidden&&ts-last>30){last=ts;t+=.03;draw()}requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);
